interface Request { id: string; }

const inflight = new Map<Request, AbortController>();

function track(req: Request): AbortController {
  let ctrl = inflight.get(req);
  if (!ctrl) {
    ctrl = new AbortController();
    inflight.set(req, ctrl);
  }
  return ctrl;
}

function uniqueBy<T, K>(items: T[], keyFn: (item: T) => K): T[] {
  const seen = new Set<K>();
  const result: T[] = [];
  for (const item of items) {
    const key = keyFn(item);
    if (!seen.has(key)) {
      seen.add(key);
      result.push(item);
    }
  }
  return result;
}

type ListenerMeta = { count: number };
const listenerMeta = new WeakMap<EventTarget, ListenerMeta>();

function attach(el: EventTarget): void {
  const meta = listenerMeta.get(el) ?? { count: 0 };
  meta.count += 1;
  listenerMeta.set(el, meta);
}

